     "t": "svg",
     "svg": "<svg viewBox=\"0 0 420 316\" role=\"img\" aria-label=\"Library management class map\">\n<rect class=\"d-acc\" x=\"115\" y=\"6\" width=\"190\" height=\"48\" rx=\"6\"/><text class=\"d-b\" x=\"125\" y=\"26\">Library</text><text class=\"d-s\" x=\"125\" y=\"44\">borrow, return, search</text>\n<rect class=\"d-box\" x=\"20\" y=\"100\" width=\"190\" height=\"48\" rx=\"6\"/><text class=\"d-b\" x=\"30\" y=\"120\">Book</text><text class=\"d-s\" x=\"30\" y=\"138\">isbn, title, copies</text>\n<path class=\"d-ar\" d=\"M115 30 L10 30 L10 124 L18 124\"/>\n<rect class=\"d-box\" x=\"20\" y=\"172\" width=\"190\" height=\"48\" rx=\"6\"/><text class=\"d-b\" x=\"30\" y=\"192\">Copy</text><text class=\"d-s\" x=\"30\" y=\"210\">borrower, due</text>\n<path class=\"d-ar\" d=\"M115 30 L10 30 L10 196 L18 196\"/>\n<rect class=\"d-box\" x=\"20\" y=\"244\" width=\"190\" height=\"48\" rx=\"6\"/><text class=\"d-b\" x=\"30\" y=\"264\">Member</text><text class=\"d-s\" x=\"30\" y=\"282\">loans, fines</text>\n<path class=\"d-ar\" d=\"M115 30 L10 30 L10 268 L18 268\"/>\n<rect class=\"d-dashbox\" x=\"224\" y=\"100\" width=\"180\" height=\"48\" rx=\"6\"/><text class=\"d-b\" x=\"234\" y=\"120\">Constants</text><text class=\"d-s\" x=\"234\" y=\"138\">14 days, 2, 25 cents</text>\n<path class=\"d-ar\" d=\"M305 30 L412 30 L412 124 L406 124\"/>\n<text class=\"d-a\" x=\"14\" y=\"22\">owns</text>\n<text class=\"d-a\" x=\"352\" y=\"22\">uses</text>\n</svg>",
